mapper.update:
update cms_topic_completion_coupon_reward_log set history_id = #{historyId}
where topic_id = #{topicId} and member_id = #{memberId} and coupon_id = #{couponId}
  and history_id is null

mapper.select:
select created_at from cms_topic_completion_coupon_reward_log
where topic_id = #{topicId} and member_id = #{memberId}
order by created_at asc limit 1
